function isValidBST(root) {
  const a = [];
  const go = (n) => { if (!n) return; go(n.left); a.push(n.val); go(n.right); };
  go(root);
  for (let i = 1; i < a.length; i++) if (a[i] <= a[i - 1]) return false;
  return true;
}
